alter table public.profiles add column if not exists email text;
update public.profiles p set email=u.email from auth.users u where u.id=p.id and p.email is null;
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,full_name,email) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',split_part(new.email,'@',1)),new.email) on conflict(id) do update set email=excluded.email; return new; end; $$;
create table if not exists public.admin_audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid not null references auth.users(id),action text not null,entity_type text not null,entity_id text,details jsonb not null default '{}'::jsonb,created_at timestamptz not null default now());
create index if not exists admin_audit_logs_created_idx on public.admin_audit_logs(created_at desc);
alter table public.admin_audit_logs enable row level security;
drop policy if exists "Admins read audit logs" on public.admin_audit_logs;
create policy "Admins read audit logs" on public.admin_audit_logs for select using(public.is_admin());
create or replace function public.set_administrator(target_user uuid,make_admin boolean) returns void language plpgsql security definer set search_path='' as $$ declare old_role public.user_role; new_role public.user_role:=case when make_admin then 'admin'::public.user_role else 'customer'::public.user_role end; begin if not public.is_admin() then raise exception 'Administrator access required'; end if; if target_user=auth.uid() and not make_admin then raise exception 'You cannot remove your own administrator access'; end if; select role into old_role from public.profiles where id=target_user for update; if old_role is null then raise exception 'Account not found'; end if; update public.profiles set role=new_role where id=target_user; insert into public.admin_audit_logs(actor_id,action,entity_type,entity_id,details) values(auth.uid(),case when make_admin then 'admin.promoted' else 'admin.demoted' end,'profile',target_user::text,jsonb_build_object('previous_role',old_role,'new_role',new_role)); end; $$;
grant execute on function public.set_administrator(uuid,boolean) to authenticated;
create or replace function public.write_admin_log(log_action text,log_entity_type text,log_entity_id text default null,log_details jsonb default '{}'::jsonb) returns void language plpgsql security definer set search_path='' as $$ begin if not public.is_admin() then raise exception 'Administrator access required'; end if; insert into public.admin_audit_logs(actor_id,action,entity_type,entity_id,details) values(auth.uid(),log_action,log_entity_type,log_entity_id,coalesce(log_details,'{}'::jsonb)); end; $$;
grant execute on function public.write_admin_log(text,text,text,jsonb) to authenticated;
